script:
frappe.listview_settings['Employee Monthly Timesheet'] = {
    onload(listview) {
        listview.page.add_inner_button(__('Download Bulk Timesheets'), function() {
            let d = new frappe.ui.Dialog({
                title: 'Generate Timesheet PDFs',
                fields: [
                    { label: 'Year', fieldname: 'year', fieldtype: 'Int', default: new Date().getFullYear(), reqd: 1 },
                    { label: 'Month', fieldname: 'month', fieldtype: 'Int', default: new Date().getMonth() + 1, reqd: 1 }
                ],
                primary_action_label: 'Generate',
                primary_action(values) {
                    d.hide();
                    frappe.dom.freeze("Generating ZIP file... Please wait");
                    frappe.call({
                        method: "hrms.api.api.generate_bulk_timesheet_pdfs",
                        args: { year: values.year, month: values.month },
                        callback: function(r) {
                            frappe.dom.unfreeze();
                            if (!r.exc && r.message) {
                                frappe.msgprint({
                                    title: __('Download Start'),
                                    message: `<a href="/app/bulk-monthly-timesheet/${r.message.record}" target="_blank">Go to Employee Monthly Timesheet</a>`,
                                    indicator: 'green'
                                });

                            }
                        }
                    });
                }
            });
            d.show();
        });
    }
};
